svg.script:
(() => {
  const svg = document.getElementById('doc-root');
  const hud = document.getElementById('hud');
  const indicator = document.getElementById('hud-indicator');
  const btnPrev = document.getElementById('btn-prev');
  const btnNext = document.getElementById('btn-next');

  const TOTAL_PAGES = 2;
  const VIEW_W      = 242.0000;
  const VIEW_H      = 337.0000;
  const STRIDE_X    = 278.0000;
  const DURATION_MS = 380;

  let currentPage = 0;
  let currentX    = 0;
  let animId      = null;
  let wheelLock   = false;

  function applyViewport(x) {
    currentX = x;
    svg.setAttribute('viewBox', `${x.toFixed(3)} 0 ${VIEW_W} ${VIEW_H}`);
    hud.setAttribute('transform', `translate(${x.toFixed(3)}, 0)`);
  }

  function syncHudState() {
    indicator.textContent = `P\u00e1g. ${currentPage + 1} / ${TOTAL_PAGES}`;
    btnPrev.classList.toggle('hud-btn-disabled', currentPage <= 0);
    btnNext.classList.toggle('hud-btn-disabled', currentPage >= TOTAL_PAGES - 1);
  }

  function goToPage(targetIdx, immediate = false) {
    const clamped = Math.max(0, Math.min(TOTAL_PAGES - 1, targetIdx));
    currentPage = clamped;
    const targetX = clamped * STRIDE_X;
    syncHudState();

    try { history.replaceState(null, '', `#page=${clamped + 1}`); } catch (_) {}

    if (animId !== null) {
      cancelAnimationFrame(animId);
      animId = null;
    }

    if (immediate || Math.abs(targetX - currentX) < 0.05) {
      applyViewport(targetX);
      return;
    }

    const startX = currentX;
    const deltaX = targetX - startX;
    const startTime = performance.now();

    function tick(now) {
      const elapsed = now - startTime;
      const t = Math.min(1, elapsed / DURATION_MS);
      const ease = 1 - Math.pow(1 - t, 3);
      applyViewport(startX + deltaX * ease);
      if (t < 1) {
        animId = requestAnimationFrame(tick);
      } else {
        animId = null;
      }
    }
    animId = requestAnimationFrame(tick);
  }

  btnPrev.addEventListener('click', () => goToPage(currentPage - 1));
  btnNext.addEventListener('click', () => goToPage(currentPage + 1));

  window.addEventListener('keydown', (ev) => {
    if (ev.key === 'ArrowRight' || ev.key === 'PageDown' || ev.key === ' ') {
      ev.preventDefault();
      goToPage(currentPage + 1);
    } else if (ev.key === 'ArrowLeft' || ev.key === 'PageUp') {
      ev.preventDefault();
      goToPage(currentPage - 1);
    } else if (ev.key === 'Home') {
      ev.preventDefault();
      goToPage(0);
    } else if (ev.key === 'End') {
      ev.preventDefault();
      goToPage(TOTAL_PAGES - 1);
    }
  });

  window.addEventListener('wheel', (ev) => {
    if (wheelLock) return;
    const delta = Math.abs(ev.deltaX) > Math.abs(ev.deltaY) ? ev.deltaX : ev.deltaY;
    if (Math.abs(delta) < 18) return;
    wheelLock = true;
    goToPage(currentPage + (delta > 0 ? 1 : -1));
    setTimeout(() => { wheelLock = false; }, 320);
  }, { passive: true });

  const match = /^#page=(\d+)$/.exec(window.location.hash);
  const initial = match ? parseInt(match[1], 10) - 1 : 0;
  goToPage(isNaN(initial) ? 0 : initial, true);
})();
